using System;using System.IO;using System.Net;using System.Text;using System.Globalization;using System.Collections;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;
namespace IslandIntegrated {
 // Request-local recovery only. Never changes proxy, TLS policy, credentials or routes.
 public sealed class WeatherRequestException:Exception {
  public readonly string Code;public readonly int? HttpStatus;public readonly DateTimeOffset? RetryAt;
  public WeatherRequestException(string code,int? status=null,DateTimeOffset? retryAt=null):base(code){Code=code;HttpStatus=status;RetryAt=retryAt;}
  public static DateTimeOffset? ParseRetryAfter(string value,DateTimeOffset now){
   double seconds;if(Double.TryParse(value,NumberStyles.None,CultureInfo.InvariantCulture,out seconds)&&!Double.IsNaN(seconds)&&!Double.IsInfinity(seconds)&&seconds>=0&&seconds<=31536000)return now.AddSeconds(seconds);
   DateTimeOffset date;if(DateTimeOffset.TryParse(value,CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal,out date)&&date>now&&date<=now.AddYears(1))return date.ToUniversalTime();return null;
  }
  public static WeatherRequestException Describe(Exception error,DateTimeOffset now){
   var known=error as WeatherRequestException;if(known!=null)return known;
   var web=error as WebException;if(web!=null){var response=web.Response as HttpWebResponse;int? status=null;DateTimeOffset? retry=null;if(response!=null){try{status=(int)response.StatusCode;retry=ParseRetryAfter(response.Headers["Retry-After"],now);}finally{response.Dispose();}}
    string code=status==429?"rate-limited":status==407?"proxy-authentication":status.HasValue?"http-error":web.Status==WebExceptionStatus.Timeout||web.Status==WebExceptionStatus.RequestCanceled?"timeout":web.Status==WebExceptionStatus.TrustFailure?"certificate":web.Status==WebExceptionStatus.SecureChannelFailure?"secure-channel":"transport";return new WeatherRequestException(code,status,retry);
   }
   return new WeatherRequestException(error is OperationCanceledException?"timeout":error is InvalidDataException||error is ArgumentException||error is InvalidOperationException||error is FormatException?"invalid-response":"transport");
  }
 }
 public sealed class WeatherRequestChannel {
  readonly SemaphoreSlim gate=new SemaphoreSlim(1,1);readonly object state=new object();readonly Func<DateTimeOffset> clock;WeatherRequestException failure;
  public WeatherRequestChannel(Func<DateTimeOffset> clock){this.clock=clock;}
  public bool HasFailure {get{lock(state)return failure!=null;}}
  public async Task<T> RunAsync<T>(Func<Task<T>> operation,CancellationToken token){
   await gate.WaitAsync(token).ConfigureAwait(false);try{
    token.ThrowIfCancellationRequested();var now=clock();lock(state){if(failure!=null&&failure.RetryAt.HasValue&&now<failure.RetryAt.Value)throw failure;}
    T result;try{result=await operation().ConfigureAwait(false);token.ThrowIfCancellationRequested();}
    catch(Exception error){token.ThrowIfCancellationRequested();var described=WeatherRequestException.Describe(error,clock());var observed=clock();double minimum=described.Code=="rate-limited"?60:described.Code=="invalid-response"||described.Code=="proxy-authentication"||described.HttpStatus>=400&&described.HttpStatus<500?300:30;
     var retry=observed.AddSeconds(minimum);if(described.RetryAt.HasValue&&described.RetryAt.Value>retry)retry=described.RetryAt.Value;var next=new WeatherRequestException(described.Code,described.HttpStatus,retry);lock(state)failure=next;throw next;
    }
    lock(state)failure=null;return result;
   }finally{gate.Release();}
  }
 }

 // Only explicit city-center requests. Never discovers GPS, IP location or device coordinates.
 public sealed class OpenMeteoWeatherProvider:IWeatherProvider {
  public readonly WeatherPlace Location;public bool CitySearchEnabled {get;private set;}
  readonly Uri endpoint;readonly Func<Uri,CancellationToken,Task<string>> fetch;readonly WeatherMemoryCache cache;readonly Func<DateTimeOffset> clock;readonly WeatherRequestChannel forecastRequests,searchRequests;
  public OpenMeteoWeatherProvider(string city,double latitude,double longitude,Func<Uri,CancellationToken,Task<string>> transport=null,bool citySearchApproved=false,Func<DateTimeOffset> utcClock=null):this(new WeatherPlace{Name=city,Latitude=latitude,Longitude=longitude},transport,citySearchApproved,new WeatherMemoryCache(),utcClock??(()=>DateTimeOffset.UtcNow),null,null){}
  OpenMeteoWeatherProvider(WeatherPlace place,Func<Uri,CancellationToken,Task<string>> transport,bool search,WeatherMemoryCache shared,Func<DateTimeOffset> utcClock,WeatherRequestChannel forecast,WeatherRequestChannel geocode){if(place==null||!place.Valid)throw new ArgumentException("city-center place");Location=place;endpoint=BuildUri(place.Latitude,place.Longitude);fetch=transport??Fetch;CitySearchEnabled=search;cache=shared;clock=utcClock;forecastRequests=forecast??new WeatherRequestChannel(clock);searchRequests=geocode??new WeatherRequestChannel(clock);}
  public OpenMeteoWeatherProvider ForPlace(WeatherPlace place){return new OpenMeteoWeatherProvider(place,fetch,CitySearchEnabled,cache,clock,forecastRequests,searchRequests);}
  public static IWeatherProvider FromApprovedConfiguration(string file){try{if(!File.Exists(file)||new FileInfo(file).Length>16384)return new DisconnectedWeatherProvider();var json=new JavaScriptSerializer{MaxJsonLength=16384,RecursionLimit=8}.DeserializeObject(File.ReadAllText(file)) as IDictionary<string,object>;object service,enabled,name,search;if(json==null||!json.TryGetValue("service",out service)||!String.Equals(service as string,"open-meteo",StringComparison.Ordinal)||!json.TryGetValue("enabled",out enabled)||!(enabled is bool)||!(bool)enabled||!json.TryGetValue("city",out name))return new DisconnectedWeatherProvider();var lat=Number(json,"cityLatitude");var lon=Number(json,"cityLongitude");if(!lat.HasValue||!lon.HasValue)return new DisconnectedWeatherProvider();bool allowSearch=json.TryGetValue("allowCitySearch",out search)&&search is bool&&(bool)search;return new OpenMeteoWeatherProvider(name as string,lat.Value,lon.Value,null,allowSearch);}catch{return new DisconnectedWeatherProvider();}}
  public static Uri BuildUri(double latitude,double longitude){if(!new WeatherPlace{Name="city",Latitude=latitude,Longitude=longitude}.Valid)throw new ArgumentException("city-center coordinates");return new Uri("https://api.open-meteo.com/v1/forecast?latitude="+latitude.ToString("0.00",CultureInfo.InvariantCulture)+"&longitude="+longitude.ToString("0.00",CultureInfo.InvariantCulture)+"&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m,precipitation&hourly=temperature_2m,precipitation_probability,precipitation,weather_code&daily=temperature_2m_max,temperature_2m_min,weather_code,precipitation_sum&timezone=auto&timeformat=unixtime&forecast_days=7");}
  public static Uri SearchUri(string query){if(!WeatherSnapshot.ValidCity(query))throw new ArgumentException("city search");return new Uri("https://geocoding-api.open-meteo.com/v1/search?name="+Uri.EscapeDataString(query.Trim())+"&count=6&language=zh&format=json");}
  static async Task<string> Fetch(Uri uri,CancellationToken token){bool forecast=uri.Host=="api.open-meteo.com"&&uri.AbsolutePath=="/v1/forecast",search=uri.Host=="geocoding-api.open-meteo.com"&&uri.AbsolutePath=="/v1/search";if(uri.Scheme!="https"||uri.Port!=443||(!forecast&&!search))throw new InvalidOperationException("Weather endpoint denied");var request=(HttpWebRequest)WebRequest.Create(uri);request.Method="GET";request.AllowAutoRedirect=false;request.Timeout=8000;request.ReadWriteTimeout=8000;request.Accept="application/json";request.UserAgent="Sidebar-Weather/1";
   using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(8000);using(timeout.Token.Register(()=>request.Abort()))using(var response=(HttpWebResponse)await request.GetResponseAsync().ConfigureAwait(false)){if(response.StatusCode!=HttpStatusCode.OK||response.ContentLength>262144)throw new InvalidDataException("Weather response rejected");using(var input=response.GetResponseStream())using(var output=new MemoryStream()){var buffer=new byte[4096];int read;while((read=await input.ReadAsync(buffer,0,buffer.Length,timeout.Token).ConfigureAwait(false))>0){if(output.Length+read>262144)throw new InvalidDataException("Weather response exceeds limit");output.Write(buffer,0,read);}return Encoding.UTF8.GetString(output.ToArray());}}}
  }
  static IDictionary<string,object> Root(string json){if(json==null||json.Length>262144)throw new InvalidDataException("Weather response size");var root=new JavaScriptSerializer{MaxJsonLength=262144,RecursionLimit=24}.DeserializeObject(json) as IDictionary<string,object>;if(root==null)throw new InvalidDataException("Weather object missing");return root;}
  static IDictionary<string,object> Map(IDictionary<string,object> data,string key){object v;return data.TryGetValue(key,out v)?v as IDictionary<string,object>:null;}
  static double? Numeric(object value){if(value==null||value is bool)return null;try{double n=Convert.ToDouble(value,CultureInfo.InvariantCulture);return Double.IsNaN(n)||Double.IsInfinity(n)?null:(double?)n;}catch{return null;}}
  static double? Number(IDictionary<string,object> data,string name){object v;return data.TryGetValue(name,out v)?Numeric(v):null;}
  static double? At(IDictionary<string,object> data,string key,int i){object v;var a=data.TryGetValue(key,out v)?v as IList:null;return a!=null&&i<a.Count?Numeric(a[i]):null;}
  static string Text(IDictionary<string,object> data,string key,int max){object v;var s=data.TryGetValue(key,out v)?v as string:null;return String.IsNullOrWhiteSpace(s)?"":s.Trim().Substring(0,Math.Min(max,s.Trim().Length));}
  static DateTimeOffset? Unix(double? v){return v.HasValue&&v>=0&&v<=253402300799?DateTimeOffset.FromUnixTimeSeconds((long)v.Value):(DateTimeOffset?)null;}
  static double? Range(double? v,double min,double max){return v.HasValue&&v>=min&&v<=max?v:null;}
  public static WeatherKind Kind(double? code){int c=code.HasValue?(int)code.Value:-1;return c==0?WeatherKind.Clear:c>=1&&c<=3?WeatherKind.Cloud:c>=71&&c<=77||c==85||c==86?WeatherKind.Snow:c>=51&&c<=67||c>=80&&c<=82||c>=95&&c<=99?WeatherKind.Rain:WeatherKind.Unknown;}
  public static string Description(double? code){int c=code.HasValue?(int)code.Value:-1;return c==0?"晴":c>=1&&c<=3?"多云":c==45||c==48?"雾":Kind(code)==WeatherKind.Snow?"降雪":c>=95&&c<=99?"雷雨":Kind(code)==WeatherKind.Rain?"降雨":"天气状态未知";}
  public static WeatherSnapshot Parse(string city,string json){var root=Root(json);var current=Map(root,"current");var daily=Map(root,"daily");if(current==null||daily==null)throw new InvalidDataException("Weather fields missing");var time=Unix(Number(current,"time"));if(!time.HasValue||time.Value>DateTimeOffset.UtcNow.AddMinutes(5)||time.Value<DateTimeOffset.UtcNow.AddYears(-1))throw new InvalidDataException("Weather timestamp invalid");int offset=(int)(Range(Number(root,"utc_offset_seconds"),-50400,50400)??0)/60*60;var result=new WeatherSnapshot{City=city,State="fresh",Attribution="Open-Meteo",Temperature=Number(current,"temperature_2m"),FeelsLike=Number(current,"apparent_temperature"),Humidity=Range(Number(current,"relative_humidity_2m"),0,100),WindSpeed=Range(Number(current,"wind_speed_10m"),0,500),Precipitation=Range(Number(current,"precipitation"),0,2000),High=At(daily,"temperature_2m_max",0),Low=At(daily,"temperature_2m_min",0),ObservedAt=time,OffsetSeconds=offset,Timezone=Text(root,"timezone",80),Kind=Kind(Number(current,"weather_code")),Description=Description(Number(current,"weather_code"))};
   var hourly=Map(root,"hourly");if(hourly!=null)for(int i=0;i<192&&result.Hourly.Count<48;i++){var t=Unix(At(hourly,"time",i));if(!t.HasValue)continue;if(t.Value<time.Value.AddHours(-1)||t.Value>time.Value.AddDays(8))continue;result.Hourly.Add(new WeatherHour{Time=t.Value,Temperature=Range(At(hourly,"temperature_2m",i),-100,100),PrecipitationProbability=Range(At(hourly,"precipitation_probability",i),0,100),Precipitation=Range(At(hourly,"precipitation",i),0,2000),Kind=Kind(At(hourly,"weather_code",i))});}
   for(int i=0;i<7;i++){var t=Unix(At(daily,"time",i));if(!t.HasValue||t.Value<time.Value.AddDays(-2)||t.Value>time.Value.AddDays(8))continue;var hi=Range(At(daily,"temperature_2m_max",i),-100,100);var lo=Range(At(daily,"temperature_2m_min",i),-100,100);if(hi.HasValue&&lo.HasValue&&hi<lo){hi=null;lo=null;}result.Daily.Add(new WeatherDay{Time=t.Value,High=hi,Low=lo,Precipitation=Range(At(daily,"precipitation_sum",i),0,2000),Kind=Kind(At(daily,"weather_code",i)),Description=Description(At(daily,"weather_code",i))});}return result;
  }
  public static List<WeatherPlace> ParsePlaces(string json){var root=Root(json);object value;var items=root.TryGetValue("results",out value)?value as IList:null;var results=new List<WeatherPlace>();if(items!=null)for(int i=0;i<items.Count&&results.Count<6;i++){var row=items[i] as IDictionary<string,object>;if(row==null)continue;var lat=Number(row,"latitude");var lon=Number(row,"longitude");if(!lat.HasValue||!lon.HasValue)continue;var place=new WeatherPlace{Name=Text(row,"name",60),Region=Text(row,"admin1",80),Country=Text(row,"country",80),Latitude=lat.Value,Longitude=lon.Value};if(place.Valid)results.Add(place);}return results;}
  public async Task<List<WeatherPlace>> SearchAsync(string query,CancellationToken token){if(!CitySearchEnabled)throw new InvalidOperationException("城市搜索尚未获准联网");token.ThrowIfCancellationRequested();var uri=SearchUri(query);return await searchRequests.RunAsync(async()=>ParsePlaces(await fetch(uri,token).ConfigureAwait(false)),token).ConfigureAwait(false);}
  public Task<WeatherSnapshot> ReadAsync(string city,CancellationToken token){return ReadCore(city,token,false);}public Task<WeatherSnapshot> ReadFreshAsync(string city,CancellationToken token){return ReadCore(city,token,true);}async Task<WeatherSnapshot> ReadCore(string city,CancellationToken token,bool force){
   token.ThrowIfCancellationRequested();if(!String.Equals(Location.Name,city,StringComparison.Ordinal))return new WeatherSnapshot{City=city,State="not-connected"};string key=city+"\n"+endpoint.AbsoluteUri;
   try{var hit=cache.Read(key,clock(),false);if(hit!=null&&!force&&!forecastRequests.HasFailure)return hit;
    return await forecastRequests.RunAsync(async()=>{var available=cache.Read(key,clock(),false);if(available!=null&&!force&&!forecastRequests.HasFailure)return available;var data=Parse(city,await fetch(endpoint,token).ConfigureAwait(false));token.ThrowIfCancellationRequested();if(data.EffectiveState(clock())!="fresh")throw new InvalidDataException("Weather values invalid or stale");cache.Put(key,data,clock());return data;},token).ConfigureAwait(false);
   }catch(OperationCanceledException){throw;}catch(Exception error){token.ThrowIfCancellationRequested();var reason=WeatherRequestException.Describe(error,clock());var old=cache.Read(key,clock(),true);var result=old!=null?old.FailedRefresh():new WeatherSnapshot{City=city,State="unavailable"};result.FailureCode=reason.Code;result.HttpStatus=reason.HttpStatus;result.RetryAt=reason.RetryAt;return result;}
  }
 }
}
